<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {message} from '../api'
import {leaveSeat,usageSession,type UsageSession} from '../reservations'
const route=useRoute();const data=ref<UsageSession>();const loading=ref(true);const leaving=ref(false);const confirming=ref(false);const error=ref('');const now=ref(Date.now());const serverOffset=ref(0)
const id=computed(()=>String(route.params.reservationId??''))
function local(value:string){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'medium',hourCycle:'h23'}).format(new Date(value))}
function duration(seconds:number){const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
const elapsed=computed(()=>{if(!data.value)return'00:00:00';const end=data.value.completedAt?Date.parse(data.value.completedAt):now.value+serverOffset.value;return duration(Math.max(0,Math.floor((end-Date.parse(data.value.checkedInAt))/1000)))})
const active=computed(()=>data.value?.status==='CHECKED_IN')
async function load(){loading.value=true;error.value='';try{const value=await usageSession(id.value);serverOffset.value=Date.parse(value.serverTime)-Date.now();data.value=value}catch(e){data.value=undefined;error.value=message(e)}finally{loading.value=false}}
async function confirmLeave(){leaving.value=true;error.value='';try{const value=await leaveSeat(id.value);serverOffset.value=Date.parse(value.serverTime)-Date.now();data.value=value;confirming.value=false}catch(e){error.value=message(e)}finally{leaving.value=false}}
let timer:ReturnType<typeof setInterval>
onMounted(()=>{void load();timer=setInterval(()=>{now.value=Date.now()},1000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="usage-page"><div class="page-heading"><div><div class="eyebrow">M1 / SEAT IN USE</div><h1>座位使用状态</h1><p>签到与退座均以服务端记录为准，刷新页面不会丢失使用状态。</p></div><RouterLink class="button secondary" to="/my-reservations">返回我的预约</RouterLink></div>
  <p v-if="loading" role="status">正在读取使用状态…</p><p v-if="error" class="form-error" role="alert">{{error}} <button v-if="!data" class="text-link" @click="load">重试</button></p>
  <section v-if="data" class="panel usage-card" aria-live="polite"><div class="usage-status"><span class="live-ring" :class="{stopped:!active}"/><div><span>{{active?'CURRENT SESSION':'SESSION FINISHED'}}</span><h2>{{active?'座位使用中':'本次使用已结束'}}</h2></div><span class="badge" :class="{neutral:!active}">{{active?'使用中':'已退座'}}</span></div>
    <div class="timer-block"><span>{{active?'已使用时长':'本次使用时长'}}</span><strong>{{elapsed}}</strong><small>{{active?'计时来自服务端签到时刻':'已按服务端退座时刻停止计时'}}</small></div>
    <dl class="usage-details"><dt>签到时间</dt><dd>{{local(data.checkedInAt)}}（上海）</dd><dt>预约时段</dt><dd>{{local(data.startAt)}} — {{local(data.endAt)}}</dd><dt>教室编号</dt><dd class="mono">{{data.roomId}}</dd><dt>座位编号</dt><dd class="mono">{{data.seatId}}</dd><template v-if="data.completedAt"><dt>退座时间</dt><dd>{{local(data.completedAt)}}（上海）</dd></template></dl>
    <div v-if="active" class="leave-zone"><template v-if="!confirming"><p>离开座位时请及时退座，确认后本次使用将结束。</p><button class="button danger-button" @click="confirming=true">结束使用并退座</button></template><template v-else><p class="confirm-text">确认现在结束使用并释放该座位吗？</p><div class="confirm-actions"><button class="button secondary" :disabled="leaving" @click="confirming=false">继续使用</button><button class="button danger-button" :disabled="leaving" @click="confirmLeave">{{leaving?'正在退座…':'确认退座'}}</button></div></template></div>
    <div v-else class="finished-note"><strong>退座成功</strong><p>本次座位使用已经结束，可返回“我的预约”查看记录。</p></div>
  </section></div></template>
<style scoped>.usage-page{max-width:920px;margin:0 auto}.usage-card{padding:34px}.usage-status{display:flex;align-items:center;gap:14px;border-bottom:1px solid #e3e9df;padding-bottom:24px}.usage-status>div{flex:1}.usage-status span{font-size:11px;letter-spacing:.16em;color:#79906f}.usage-status h2{font-size:24px;margin:4px 0 0}.live-ring{width:18px;height:18px;border:5px solid #dcebd5;border-radius:50%;background:#4f8b62;box-shadow:0 0 0 6px #eef5ea}.live-ring.stopped{background:#97a294;border-color:#e1e5df;box-shadow:none}.timer-block{text-align:center;padding:42px 0 34px}.timer-block>span,.timer-block small{display:block;color:#788675}.timer-block strong{display:block;font:600 clamp(48px,9vw,82px)/1.2 "SFMono-Regular",Consolas,monospace;letter-spacing:.06em;color:#173e32;margin:10px 0}.usage-details{display:grid;grid-template-columns:130px 1fr;gap:14px 20px;background:#f6f8f3;border-radius:14px;padding:24px}.usage-details dt{color:#82907d}.usage-details dd{margin:0;overflow-wrap:anywhere}.leave-zone,.finished-note{margin-top:24px;padding:22px;border:1px solid #e2e7de;border-radius:14px}.leave-zone{display:flex;align-items:center;justify-content:space-between;gap:20px}.leave-zone p{margin:0;color:#6e7c69}.danger-button{background:#9b4a3f;border-color:#9b4a3f}.confirm-text{font-weight:600;color:#743b34!important}.confirm-actions{display:flex;gap:10px}.finished-note{background:#edf5e9;color:#456342}.finished-note p{margin:6px 0 0}@media(max-width:650px){.usage-card{padding:22px}.usage-status{align-items:flex-start}.usage-details{grid-template-columns:1fr;gap:5px}.usage-details dd{margin-bottom:12px}.leave-zone{align-items:stretch;flex-direction:column}.confirm-actions{display:grid}.timer-block strong{letter-spacing:.02em}}</style>
